#### Versão 3: Correção Suave com Interpolação (Smooth Transition/Lerp)
**Conceito:** Em vez de definir um valor instantaneamente (hard snap), usamos `lerp` (Linear Interpolation) para mover a velocidade em direção ao alvo gradualmente, gerando uma sensação mais natural.

```javascript
// V3: Correção Suave com Interpolação (Lerp)
adjustSynchronizationV3(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const lerpFactor = 0.1; // Controla a suavidade (0.1 = suave; 0.9 = rápido)

    let targetSpeed;
    let targetVideoRate = 1.0;

    if (timeDifference < 500) {
        targetSpeed = maxSpeed;
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 1.2 : 1.0;
    } else if (timeDifference > 1000) {
        targetSpeed = 1.2;
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 0.8 : 1.0;
    } else {
        targetSpeed = this.userConfiguredSpeed;
        targetVideoRate = 1.0;
    }

    // Aplica Lerp ao controle de velocidade
    this.speedControl.value = lerp(this.speedControl.value, targetSpeed, lerpFactor);

    // Aplica Lerp ao playback rate do vídeo
    this.video.playbackRate = lerp(this.video.playbackRate, targetVideoRate, lerpFactor);

    this.updateRangeValue('speed');
}

// Função auxiliar de Lerp:
function lerp(start, end, t) { return start * (1 - t) + end * t; }
