// V9: Ajuste de Velocidade Específico do Modo
adjustSynchronizationV9(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const isSlowDownMode = this.speakingControlMode === 'slowDown';

    if (timeDifference < 500) { // Atrasado
        // Se em slowDown, ajustamos mais agressivamente para compensar o atraso.
        const speedFactor = isSlowDownMode ? 1.5 : 1.2;
        this.speedControl.value = maxSpeed * speedFactor;

        if (isSlowDownMode) {
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.2, 2.0); // Mais agressivo
        }
    } else if (timeDifference > 1000) { // Adiantado
        // Se em slowDown, o desaceleração precisa ser mais suave para não quebrar a imersão.
        const speedFactor = isSlowDownMode ? 0.8 : 1.2;
        this.speedControl.value = speedFactor;

        if (isSlowDownMode) {
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 0.5); // Mais suave
        }
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
    }
