#### Versão 10: Ajuste Misto de Ponderação (Weighted Hybrid Adjustment)
**Conceito:** Esta versão combina o conceito de proporção (V1) com a suavização (V3). O ajuste de velocidade é proporcional ao erro, mas o *aplicação* desse ajuste é gradual (usando Lerp).

```javascript
// V10: Ajuste Misto de Ponderação (Weighted Hybrid)
adjustSynchronizationV10(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const lerpFactor = 0.05; // Fator de suavização (bem baixo para ser muito suave)
    const baseSpeed = this.userConfiguredSpeed;

    let targetSpeed;
    let targetVideoRate = 1.0;

    if (timeDifference < 500) { 
        // Target proporcional ao erro
        const proportionalSpeed = 1 + (500 - Math.abs(timeDifference)) / 500 * 0.5; 
        targetSpeed = Math.min(maxSpeed, baseSpeed * proportionalSpeed);
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 1.3 : 1.0;
    } else if (timeDifference > 1000) { 
        // Target proporcional ao erro
        const proportionalSpeed = 1 - Math.abs(timeDifference - 1000) / 1000 * 0.5;
        targetSpeed = Math.max(0.7, baseSpeed * proportionalSpeed);
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 0.7 : 1.0;
    } else {
        targetSpeed = baseSpeed;
        targetVideoRate = 1.0;
    }

    // Aplica Lerp para suavizar a transição para o alvo dinâmico
    this.speedControl.value = lerp(this.speedControl.value, targetSpeed, lerpFactor);
    this.video.playbackRate = lerp(this.video.playbackRate, targetVideoRate, lerpFactor);

    this.updateRangeValue('speed');
}

// Função auxiliar de Lerp (necessária para V3 e V10):
function lerp(start, end, t) { return start * (1 - t) + end * t; }
```

