Antes das variações, aqui está uma versão ligeiramente refatorada e mais limpa do código original, que servirá de ponto de partida para os ajustes mais complexos:

```javascript
adjustSynchronization(currentTime) {
    // Verifica se há elementos necessários para evitar erros de runtime
    if (this.speechQueue.length === 0 || !this.dubbingMode || this.dubbingMode !== 'advanced') {
        return;
    }

    const nextSpeechTime = this.speechQueue[0].startTime;
    const timeDifference = nextSpeechTime - currentTime;

    if (timeDifference < 0) {
        // Tratamento de erro: Se o tempo já passou, mas ainda não foi disparado
        console.warn("Atraso crítico detectado. Forçando ajuste de velocidade.");
    }

    // --- LÓGICA DE AJUSTE PRINCIPAL ---
    if (timeDifference < 500) { // Dublagem Atrasada (Latency)
        // Ajusta o áudio para acelerar a fala
        this.speedControl.value = parseFloat(this.maxSpeedControl.value) || 2.0;

        if (this.speakingControlMode === 'slowDown') {
            // Ajuste de vídeo ao atrasar o áudio
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 1.5); // Ajuste de limite sugerido
        }
    } else if (timeDifference > 1000) { // Dublagem Adiantada (Anticipation)
        // Volta o áudio para um ritmo mais padrão
        this.speedControl.value = 1.2; 

        if (this.speakingControlMode === 'slowDown') {
            // Ajuste de vídeo ao adiantar o áudio
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.1, 0.8); // Ajuste de limite sugerido
        }
    } else { // Sincronizado
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0; // Reset do vídeo
    }

    this.updateRangeValue('speed');
}
```

