### 🚀 As 10 Versões Avançadas

#### Versão 1: Ajuste Proporcional Inteligente (Dynamic Correction)
**Conceito:** Em vez de valores fixos (`+0.1`), o ajuste de velocidade é proporcional ao erro. Se o atraso for de 2000ms, o ajuste será maior do que se for de 1000ms.

```javascript
// V1: Ajuste Proporcional Inteligente
adjustSynchronizationV1(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const correctionFactor = 0.001; // Fator de sensibilidade

    if (Math.abs(timeDifference) > 200) {
        // Calcula o fator de aceleração/desaceleração
        const adjustmentRatio = timeDifference * correctionFactor;

        if (timeDifference < 0) { // Atrasado (Negative Time Difference means future time is earlier than now)
            this.speedControl.value = Math.min(maxSpeed, 1 + adjustmentRatio);
            // Ajuste de vídeo: Mais atrasado = mais aceleração de vídeo para compensar a fala mais rápida
            this.video.playbackRate = Math.min(this.video.playbackRate + adjustmentRatio * 0.5, 2.0);
        } else if (timeDifference > 1000) { // Adiantado
            this.speedControl.value = Math.max(0.5, 1 - adjustmentRatio);
            // Ajuste de vídeo: Mais adiantado = mais desaceleração de vídeo
            this.video.playbackRate = Math.max(this.video.playbackRate - adjustmentRatio * 0.5, 0.5);
        } else {
            this.speedControl.value = this.userConfiguredSpeed;
            this.video.playbackRate = 1.0;
        }
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
    }
    this.updateRangeValue('speed');
}
```

#### Versão 2: Priorização Absoluta do Áudio (Audio Dominance)
**Conceito:** O ajuste do vídeo é minimizado. A prioridade máxima é usar o `maxSpeedControl` para forçar o áudio a sincronizar, tratando o vídeo como um elemento secundário.

```javascript
// V2: Priorização Absoluta do Áudio
adjustSynchronizationV2(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;

    if (timeDifference < 500) { // Atrasado
        this.speedControl.value = maxSpeed;
        // Mantém o vídeo estático ou com mínimo ajuste
        if (this.speakingControlMode === 'slowDown') {
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.05, 1.2); 
        }
    } else if (timeDifference > 1000) { // Adiantado
        this.speedControl.value = 1.2;
        // Se estiver adiantado, o vídeo é apenas ligeiramente ajustado para "suavizar" o ritmo.
        if (this.speakingControlMode === 'slowDown') {
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 0.8); 
        }
    } else {
        // Sincronizado
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0; 
    }
    this.updateRangeValue('speed');
}
```

#### Versão 3: Correção Suave com Interpolação (Smooth Transition/Lerp)
**Conceito:** Em vez de definir um valor instantaneamente (hard snap), usamos `lerp` (Linear Interpolation) para mover a velocidade em direção ao alvo gradualmente, gerando uma sensação mais natural.

```javascript
// V3: Correção Suave com Interpolação (Lerp)
adjustSynchronizationV3(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const lerpFactor = 0.1; // Controla a suavidade (0.1 = suave; 0.9 = rápido)

    let targetSpeed;
    let targetVideoRate = 1.0;

    if (timeDifference < 500) {
        targetSpeed = maxSpeed;
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 1.2 : 1.0;
    } else if (timeDifference > 1000) {
        targetSpeed = 1.2;
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 0.8 : 1.0;
    } else {
        targetSpeed = this.userConfiguredSpeed;
        targetVideoRate = 1.0;
    }

    // Aplica Lerp ao controle de velocidade
    this.speedControl.value = lerp(this.speedControl.value, targetSpeed, lerpFactor);

    // Aplica Lerp ao playback rate do vídeo
    this.video.playbackRate = lerp(this.video.playbackRate, targetVideoRate, lerpFactor);

    this.updateRangeValue('speed');
}

// Função auxiliar de Lerp:
function lerp(start, end, t) { return start * (1 - t) + end * t; }
```

#### Versão 4: Estratégia de Correção em Múltiplas Etapas (Multi-Stage Thresholding)
**Conceito:** Divide o erro em faixas (e.g., Pequeno, Médio, Crítico). Ajustes menores para erros pequenos, e ajustes agressivos para erros críticos.

```javascript
// V4: Estratégia de Correção em Múltiplas Etapas
adjustSynchronizationV4(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;

    if (timeDifference < -200) { // Crítico (Atraso Severo)
        this.speedControl.value = maxSpeed;
        this.video.playbackRate = Math.min(this.video.playbackRate + 0.3, 2.5); // Ajuste muito forte
    } else if (timeDifference < 500) { // Médio (Atraso Moderado)
        this.speedControl.value = 1.5;
        this.video.playbackRate = Math.min(this.video.playbackRate + 0.1, 1.5);
    } else if (timeDifference > 1000) { // Crítico (Adiantado Severo)
        this.speedControl.value = 0.7;
        this.video.playbackRate = Math.max(this.video.playbackRate - 0.3, 0.5); // Ajuste muito forte
    } else if (timeDifference > 0) { // Pequeno (Adiantamento Leve)
        this.speedControl.value = 1.1;
        this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 0.9); 
    } else {
        // Sincronizado ou muito próximo
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0; 
    }
    this.updateRangeValue('speed');
}
```

#### Versão 5: Adaptação Baseada no Estado Atual (State-Aware Adjustment)
**Conceito:** O ajuste de velocidade não só depende do erro, mas também do estado de velocidade *atual*. Se já estiver muito rápido, o ajuste será mais conservador.

```javascript
// V5: Adaptação Baseada no Estado Atual
adjustSynchronizationV5(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const currentSpeed = parseFloat(this.speedControl.value);

    if (timeDifference < 500) { // Atrasado
        // Ajuste dinâmico, mas com um limite para não acelerar demais se já estiver rápido
        let targetSpeed = maxSpeed;
        if (currentSpeed > 1.8) targetSpeed = 1.8; 
        this.speedControl.value = Math.max(currentSpeed, targetSpeed);

        if (this.speakingControlMode === 'slowDown') {
            // O vídeo só acelera se a velocidade atual não for muito alta
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.05, 1.5);
        }
    } else if (timeDifference > 1000) { // Adiantado
        // Evita desacelerar mais do que o necessário
        let targetSpeed = 1.2;
        if (currentSpeed < 0.8) targetSpeed = 0.8; 
        this.speedControl.value = Math.min(currentSpeed, targetSpeed);

        if (this.speakingControlMode === 'slowDown') {
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 0.6);
        }
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
    }
    this.updateRangeValue('speed');
}
```

#### Versão 6: Filtro de Ruído (Temporal Averaging)
**Conceito:** Em vez de reagir a cada micro-erro, usamos uma média ponderada dos últimos N ajustes. Isso suaviza flutuações rápidas e garante que o sistema não "oscile" entre aceleração e desaceleração.

```javascript
// V6: Filtro de Ruído (Temporal Averaging)
// (Assume que você tem uma propriedade interna 'speedAverage' e 'count')
adjustSynchronizationV6(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    let targetSpeed = this.userConfiguredSpeed;
    let targetVideoRate = 1.0;

    if (timeDifference < 500) { 
        targetSpeed = parseFloat(this.maxSpeedControl.value);
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 1.5 : 1.0;
    } else if (timeDifference > 1000) { 
        targetSpeed = 1.2;
        targetVideoRate = (this.speakingControlMode === 'slowDown') ? 0.8 : 1.0;
    }

    // Atualiza a média (Exemplo simplificado)
    const smoothingFactor = 0.7; // Quanto mais próximo de 1, mais rápido ele reage
    this.speedAverage = this.speedAverage * (1 - smoothingFactor) + targetSpeed * smoothingFactor;

    // Aplica a média calculada
    this.speedControl.value = this.speedAverage;
    this.video.playbackRate = targetVideoRate; // O vídeo ainda pode ser instantâneo neste modelo

    this.updateRangeValue('speed');
}
```

#### Versão 7: Detecção de Tendência (Predictive Correction)
**Conceito:** Se o sistema detecta que o erro de sincronização tem consistentemente crescido (por exemplo, está sempre mais atrasado na última chamada), ele aumenta a agressividade da correção.

```javascript
// V7: Detecção de Tendência (Predictive Correction)
// (Assume que existe 'recentError' e 'trendDirection' armazenados)
adjustSynchronizationV7(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;

    // 1. Determina o fator de correção base (depende do erro)
    let correctionFactor = 0.1; 
    if (timeDifference < 500) { 
        correctionFactor = 1.0 + (1 - this.trendDirection) * 0.5; // Se a tendência for de atraso, aumenta o fator
    } else if (timeDifference > 1000) {
        correctionFactor = 0.7 - (1 - this.trendDirection) * 0.3; // Se a tendência for de adiantamento, diminui o fator
    } else {
        this.trendDirection = 0; // Reseta tendência
        return; 
    }

    // 2. Aplica a correção
    this.speedControl.value = correctionFactor * maxSpeed; 

    // 3. Atualiza a tendência
    if (timeDifference < 0) this.trendDirection = 1;
    if (timeDifference > 0) this.trendDirection = -1;

    // Ajuste de vídeo (simplificado)
    this.video.playbackRate = this.trendDirection * 0.1 + 1.0; 
    this.updateRangeValue('speed');
}
