// V9: Ajuste de Velocidade Específico do Modo
adjustSynchronizationV9(currentTime) {
    if (this.speechQueue.length === 0 || this.dubbingMode !== 'advanced') return;

    const timeDifference = this.speechQueue[0].startTime - currentTime;
    const maxSpeed = parseFloat(this.maxSpeedControl.value) || 2.0;
    const isSlowDownMode = this.speakingControlMode === 'slowDown';

    if (timeDifference < 500) { // Atrasado
