        this.speedControl.value = maxSpeed * speedFactor;

        if (isSlowDownMode) {
            this.video.playbackRate = Math.min(this.video.playbackRate + 0.2, 2.0); // Mais agressivo
        }
    } else if (timeDifference > 1000) { // Adiantado
        // Se em slowDown, o desaceleração precisa ser mais suave para não quebrar a imersão.
        const speedFactor = isSlowDownMode ? 0.8 : 1.2;
        this.speedControl.value = speedFactor;

        if (isSlowDownMode) {
            this.video.playbackRate = Math.max(this.video.playbackRate - 0.05, 0.5); // Mais suave
        }
    } else {
        this.speedControl.value = this.userConfiguredSpeed;
        this.video.playbackRate = 1.0;
    }
